<?php declare(strict_types=1);require_once __DIR__.'/includes/header.php';$entries=load_json('changelog.json',[]);?><main><section class="page-hero"><div class="container"><div class="breadcrumb"><a href="<?= e(app_url('index.php')) ?>">Home</a><span>/</span><span>Changelog</span></div><div class="eyebrow">Product history</div><h1>Built in public.</h1><p>Every change, release, and refinement is recorded here so the product’s direction stays visible.</p></div></section><section class="section"><div class="container content-grid"><div class="content-block reveal" data-reveal><div class="section-kicker">Current history</div><h2>See what changed.</h2><p>Release notes are kept as a clear timeline, with the latest version always shown by the public data source.</p><a class="button button-primary" href="<?= e(app_url('download.php')) ?>">Get latest release <span class=arrow>↗</span></a></div><div class="timeline reveal reveal-delay-1" data-reveal><?php if(!$entries):?><div class="empty-state"><div class="empty-icon">✦</div><h3>No releases found</h3><p>The changelog is waiting for its first entry.</p></div><?php else:foreach(array_reverse($entries) as $entry):?><article class="timeline-item"><div class="timeline-dot"></div><div><time><?= e(format_date((string)$entry['date'])) ?></time><h3><?= e((string)$entry['title']) ?> · <?= e((string)$entry['version']) ?></h3><p><?= e((string)$entry['description']) ?></p><span class="status-badge status-active"><?= e((string)$entry['category']) ?></span></div></article><?php endforeach;endif; ?></div></div></section></main><?php require_once __DIR__.'/includes/footer.php'; ?>
